// El último mensaje del cliente (para quién es la sugerencia).
func (q *Queries) UltimoEntranteConv(ctx context.Context, conversacionID int64) (UltimoEntranteConvRow, error) {
	row := q.db.QueryRow(ctx, ultimoEntranteConv, conversacionID)
	var i UltimoEntranteConvRow
	err := row.Scan(&i.ID, &i.Texto, &i.CreadoEn)
	return i, err
}

const usarSugerencia = `-- name: UsarSugerencia :one
UPDATE mensajeria.sugerencias
SET estado = 'usada', usada_por = coalesce(usada_por, $1), usada_en = coalesce(usada_en, $2),
    enviada_editada = $3, mensaje_enviado_id = $4, updated_at = now()
WHERE id = $5
RETURNING id, empresa_id, conversacion_id, para_mensaje_id, estado, origen, texto, fuentes, accion, error_codigo, error_detalle, calificacion, proveedor, modelo, tokens_entrada, tokens_salida, pedida_por, usada_por, usada_en, enviada_editada, mensaje_enviado_id, generada_en, created_at, updated_at
`

type UsarSugerenciaParams struct {
	UsadaPor         *int64
	UsadaEn          *time.Time
	EnviadaEditada   *bool
	MensajeEnviadoID pgtype.UUID
	ID               uuid.UUID
}

func (q *Queries) UsarSugerencia(ctx context.Context, arg UsarSugerenciaParams) (MensajeriaSugerencia, error) {
	row := q.db.QueryRow(ctx, usarSugerencia,
		arg.UsadaPor,
		arg.UsadaEn,
		arg.EnviadaEditada,
		arg.MensajeEnviadoID,
		arg.ID,
	)
	var i MensajeriaSugerencia
	err := row.Scan(
		&i.ID,
		&i.EmpresaID,
		&i.ConversacionID,
		&i.ParaMensajeID,
		&i.Estado,
		&i.Origen,
		&i.Texto,
		&i.Fuentes,
		&i.Accion,
		&i.ErrorCodigo,
		&i.ErrorDetalle,
		&i.Calificacion,
		&i.Proveedor,
		&i.Modelo,
		&i.TokensEntrada,
		&i.TokensSalida,
		&i.PedidaPor,
		&i.UsadaPor,
		&i.UsadaEn,
		&i.EnviadaEditada,
		&i.MensajeEnviadoID,
		&i.GeneradaEn,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const usoAsistente = `-- name: UsoAsistente :one

SELECT empresa_id, mes, tokens_entrada, tokens_salida, sugerencias, resumenes, tokens_reservados, avisado_80, avisado_100, updated_at FROM mensajeria.asistente_uso WHERE coalesce(empresa_id, 0) = $1::bigint AND mes = $2
`

type UsoAsistenteParams struct {
	Empresa int64
	Mes     pgtype.Date
}

// Uso -------------------------------------------------------------------------------------------
func (q *Queries) UsoAsistente(ctx context.Context, arg UsoAsistenteParams) (MensajeriaAsistenteUso, error) {
	row := q.db.QueryRow(ctx, usoAsistente, arg.Empresa, arg.Mes)
	var i MensajeriaAsistenteUso
	err := row.Scan(
		&i.EmpresaID,
		&i.Mes,
		&i.TokensEntrada,
		&i.TokensSalida,
		&i.Sugerencias,
		&i.Resumenes,
		&i.TokensReservados,
		&i.Avisado80,
		&i.Avisado100,
		&i.UpdatedAt,
	)
	return i, err
}
